package dev.unbox.client;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.client.gui.components.Button;
import java.nio.file.*;
import java.util.*;
/** Real game screens with local invitation fixtures; no cloud identity or user profile changes. */
final class SocialFlowSmokeTest {
 private static int ticks;private static boolean done;private static final List<String> checks=new ArrayList<>();private static JsonObject fixture;private static java.util.concurrent.CompletableFuture<Boolean> decision;
 static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks.add(text);}
 static void press(Minecraft mc,String label){var b=mc.screen.children().stream().filter(w->w instanceof Button x&&x.getMessage().getString().equals(label)).map(w->(Button)w).findFirst().orElseThrow();b.onPress(new net.minecraft.client.input.KeyEvent(org.lwjgl.glfw.GLFW.GLFW_KEY_ENTER,0,0));}
 static void fixture(Minecraft mc)throws Exception{fixture=new JsonObject();fixture.addProperty("updated",System.currentTimeMillis());fixture.addProperty("connected",true);var self=new JsonObject();self.addProperty("id","flow-guest");self.addProperty("kind","local");fixture.add("self",self);fixture.add("friends",new JsonArray());var list=new JsonArray();for(int i=0;i<8;i++){var v=new JsonObject();v.addProperty("id","flow-"+i);v.addProperty("receiver","flow-guest");v.addProperty("senderName","Builder "+i);v.addProperty("sender","host-"+i);v.addProperty("expires",System.currentTimeMillis()+300000);var room=new JsonObject();room.addProperty("name",i==0?"Mountains · Survival together":"Creative world "+i);room.addProperty("minecraft","26.3");room.addProperty("loader",Platform.loader().equals("fabric")?"neoforge":"fabric");v.add("room",room);list.add(v);}fixture.add("invites",list);SocialBridge.view=fixture;Files.writeString(mc.gameDirectory.toPath().resolve("unbox-social-view.json"),fixture.toString());}
 static void tick(Minecraft mc){if(done||mc.player==null||mc.getSingleplayerServer()==null)return;try{ticks++;
  if(ticks==80){fixture(mc);SocialNotifications.refresh();SocialNotifications.tick();check(SocialNotifications.pending().size()==8,"Incoming invitations create notifications");
   var f=SocialNotifications.class.getDeclaredField("arrivals");f.setAccessible(true);var arrivals=(Map<String,Long>)f.get(null);arrivals.replaceAll((k,v)->System.currentTimeMillis()-61000);SocialNotifications.refresh();SocialNotifications.tick();check(SocialNotifications.pending().isEmpty(),"Popup expires independently of invite grant");check(SocialBridge.availableWorlds().size()==8,"Expired popups remain joinable in Multiplayer");mc.setScreen(new MultiplayerHubScreen(new UnboxHomeScreen(false)));}
  if(ticks==95){Screenshot.grab(mc.gameDirectory,"multiplayer-worlds.png",mc.getMainRenderTarget(),1,c->{});check(mc.screen.children().stream().filter(w->w instanceof Button b&&b.getMessage().getString().equals("Join")).count()>0,"World list provides Join controls");String previous=System.getProperty("unbox.accountKind");System.setProperty("unbox.accountKind","local");mc.setScreen(new MultiplayerHubScreen(new UnboxHomeScreen(false)));var publicButton=mc.screen.children().stream().filter(w->w instanceof Button b&&b.getMessage().getString().equals("Public servers")).map(w->(Button)w).findFirst().orElseThrow();check(!publicButton.active,"Local accounts keep private access and cannot open public servers");if(previous==null)System.clearProperty("unbox.accountKind");else System.setProperty("unbox.accountKind",previous);
   SocialBridge.join("flow-0");check(mc.screen instanceof JoinDecisionScreen,"Version mismatch asks before restarting");check(!Files.exists(mc.gameDirectory.toPath().resolve("unbox-switch-request.json")),"Confirmation does not create a restart request");}
  if(ticks==110){Screenshot.grab(mc.gameDirectory,"join-confirmation.png",mc.getMainRenderTarget(),1,c->{});mc.screen.onClose();check(!SocialBridge.busy(),"Cancel clears the active join");check(!Files.exists(mc.gameDirectory.toPath().resolve("unbox-switch-request.json")),"Cancel keeps the game running without restart request");check(SocialBridge.notificationSeen("flow-0"),"Accepted invitation is hidden in game even when launched externally");check(SocialBridge.availableWorlds().size()==8,"Accepting does not destroy invitation access");decision=JoinDecisionScreen.confirmFiles("2 resource packs and shared mods differ.");}
  if(ticks==125){check(mc.screen instanceof JoinDecisionScreen,"Shared resource differences open confirmation");press(mc,"Cancel");check(decision.isDone()&&!decision.join(),"Cancel completes the download decision without consent");decision=JoinDecisionScreen.confirmFiles("Cached files will be reused.");}
  if(ticks==140){press(mc,"Restart and join");check(decision.isDone()&&decision.join(),"Explicit acceptance releases the download decision");decision=JoinDecisionScreen.confirmFiles("Connection may close while this prompt is open.");}
  if(ticks==145){JoinDecisionScreen.cancelPending();}
  if(ticks==150){check(decision.isDone()&&!decision.join()&&!(mc.screen instanceof JoinDecisionScreen),"Connection cancellation dismisses the outstanding confirmation");var f=SocialBridge.class.getDeclaredField("resumeId");f.setAccessible(true);f.set(null,"waiting-for-launcher");var expiry=SocialBridge.class.getDeclaredField("resumeUntil");expiry.setAccessible(true);expiry.setLong(null,System.currentTimeMillis()+60000);SocialBridge.message="Connecting to friends and checking your invitation…";mc.setScreen(SocialBridge.titleScreen());check(mc.screen instanceof JoinProgressScreen,"Post-restart title shows progress immediately");}
  if(ticks==155){Screenshot.grab(mc.gameDirectory,"join-progress.png",mc.getMainRenderTarget(),1,c->{});mc.screen.onClose();check(!SocialBridge.resuming(),"Cancel suppresses pending automatic rejoin");mc.options.guiScale().set(6);mc.resizeGui();mc.setScreen(new MultiplayerHubScreen(new UnboxHomeScreen(false)));}
  if(ticks==170){Screenshot.grab(mc.gameDirectory,"multiplayer-small.png",mc.getMainRenderTarget(),1,c->{});for(var child:mc.screen.children())if(child instanceof Button b)check(b.getX()>=0&&b.getY()>=0&&b.getX()+b.getWidth()<=mc.screen.width&&b.getY()+b.getHeight()<=mc.screen.height,"Small-screen control within viewport: "+b.getMessage().getString());JoinDiagnostics.begin();JoinDiagnostics.route("relay");JoinDiagnostics.stage("connecting");JoinDiagnostics.finish("joined");check(!JoinDiagnostics.report().toString().contains("flow-guest"),"Diagnostics omit account identity and grants");check(JoinDiagnostics.report().getAsJsonArray("attempts").size()>0,"Join outcomes exported as structured events");mc.setScreen(new NetworkDiagnosticsScreen(mc.screen));}
  if(ticks==185){Screenshot.grab(mc.gameDirectory,"network-diagnostics.png",mc.getMainRenderTarget(),1,c->{});finish(mc,null);}
 }catch(Throwable e){finish(mc,e);}}
 private static void finish(Minecraft mc,Throwable e){done=true;if(e!=null)e.printStackTrace();try{Files.writeString(mc.gameDirectory.toPath().resolve("logs/feature-smoke.json"),new Gson().toJson(Map.of("ok",e==null,"checks",checks,"error",e==null?"":e.toString())));}catch(Exception err){err.printStackTrace();}mc.stop();}
}
